import { defineComponent,h,mergeProps } from 'vue';
function safeHref(value){return typeof value==='string'&&/^(https?:\/\/|\/(?!\/)|#|\.\.?\/)/i.test(value)?value:undefined;}
export const YkBreadcrumb=defineComponent({name:'YkBreadcrumb',inheritAttrs:false,props:{items:{type:Array,default:()=>[]},label:{type:String,default:'面包屑'},separator:{type:String,default:'/'}},emits:['navigate'],setup(p,{attrs,emit}){return ()=>h('nav',mergeProps(attrs,{class:'yk-breadcrumb','aria-label':p.label}),h('ol',{},p.items.map((item,i)=>h('li',{key:i},[i?h('span',{class:'yk-breadcrumb__separator','aria-hidden':'true'},p.separator):null,i===p.items.length-1?h('span',{'aria-current':'page'},item.label):safeHref(item.href)?h('a',{href:safeHref(item.href),onClick:e=>emit('navigate',{item,index:i,event:e})},item.label):h('button',{type:'button',onClick:e=>emit('navigate',{item,index:i,event:e})},item.label)]))));}});
